impl Write for Memory{fn write(&mut self,b:&[u8])->io::Result<usize>{self.0.borrow_mut().extend_from_slice(b);Ok(b.len())}fn flush(&mut self)->io::Result<()>{Ok(())}}
fn package_case(mask:i32)->Value{
    let bytes=Memory(Rc::new(RefCell::new(vec![])));let zip=ss_core::java_runtime::KfsZip::new(Box::new(bytes.clone()));let mut root=OpcwRelationships::OpcwRelationships(Some(zip.clone()),"".into());let bookRel=RelationRef::Local(Rc::new(OpcRelation::OpcRelation("application/book+xml","urn:book","/xl/workbook.xml")));let book=root.addRelationship(bookRel.clone());let part=book.borrow_mut().createPart();let another=book.borrow_mut().createPart();
    let same=match (&part,&another){(PartRef::Base(a),PartRef::Base(b))=>Rc::ptr_eq(a,b),_=>false};let other=RelationRef::Local(Rc::new(OpcRelation::OpcRelation("application/book+xml","urn:book","/xl/workbook.xml")));let mut out=json!({"samePart":same,"sameRelation":Rc::ptr_eq(&root.getRelationship(&bookRel,-1).unwrap(),&book),"differentRelation":root.getRelationship(&other,-1).is_none(),"sameRid":Rc::ptr_eq(&root.getRelationship__2(&book.borrow().getRId()).unwrap(),&book)});
    part.getOutputStream().unwrap().unwrap().write_all(format!("<workbook mask=\"{mask}\"/>").as_bytes()).unwrap();let rels=part.getRelationships();let mut rels=rels.borrow_mut();let sheet=RelationRef::Local(Rc::new(OpcRelation::OpcRelation("application/sheet+xml","urn:sheet","/xl/worksheets/sheet#.xml")));let one=rels.addRelationship__2(sheet.clone(),1);one.borrow_mut().createPart().getOutputStream().unwrap().unwrap().write_all(b"<sheet>A&amp;B</sheet>").unwrap();
    rels.addRelationship__3(sheet.clone(),2,7);rels.addRelationship__4(sheet.clone(),Some("http://a/% [x]#{y}`^😀".into()),Some(OpcTargetMode::EXTERNAL));rels.addRelationship__5(sheet.clone(),Some("x%20 [y]".into()),Some(OpcTargetMode::INTERNAL),false);rels.addRelationship__6(sheet.clone(),Some("custom [target]".into()),Some(OpcTargetMode::EXTERNAL),"rIdCustom".into(),4);rels.addRelationship__7(sheet.clone(),Some(OpcTargetMode::EXTERNAL),"rIdNoTarget".into(),5);rels.addRelationship__8(sheet.clone(),6,"rIdSix".into());rels.addRelationship__2(sheet,7);
    let ids:Vec<_>=rels.iterator().map(|r|{let r=r.borrow();json!({"rid":r.getRId(),"index":r.getRelIndex(),"part":r.getPackagePart().map(|p|p.getPartName())})}).collect();out["ids"]=json!(ids);out["size"]=json!(rels.size());drop(rels);
    let app=root.addRelationship(RelationRef::Static(&*OxfRelations::APP)).borrow_mut().createPart();let core=root.addRelationship(RelationRef::Static(&*OxfRelations::CORE)).borrow_mut().createPart();let custom=root.addRelationship(RelationRef::Static(&*OxfRelations::CUSTOM)).borrow_mut().createPart();assert!(matches!(custom,PartRef::Custom(_)));let PartRef::App(app)=app else{panic!("App subtype")};let PartRef::Core(core)=core else{panic!("Core subtype")};let mut app=app.borrow_mut();let mut core=core.borrow_mut();out["classes"]=json!(["OxfwAppPart","OxfwCorePart","OxfwCustomPart","OpcwPackagePart"]);
    if mask&1!=0{app.setAppName(Some("WPS <&\"\nOffice".into()));app.setAppVersion(Some("1.2".into()));app.setDocSecurity(0);app.setCompany(Some("公司".into()));app.setManager(Some("Manager".into()));app.setHyperlinkBase(Some("http://a/?x&y".into()));app.setScale(true);app.setLinkDirty(true);core.setCreator(Some("作者".into()));core.setTitle(Some("Title <&>".into()));core.setDescription(Some("A\nB".into()));core.setLastModifiedBy(Some("Editor".into()));core.setKeywords(Some("a,b".into()));core.setCategory(Some("cat".into()));core.setContentStatus(Some("status".into()));core.setSubject(Some("subject".into()));}
    if mask&2!=0{core.setCreated(Some(-1));core.setModified(Some(1735689600000));}
    if mask&4!=0{app.setAppName(None);app.setAppVersion(Some("".into()));core.setCreator(None);core.setTitle(None);core.setDescription(None);core.setSubject(Some("subject-only".into()));}
    app.write().unwrap();core.write().unwrap();drop(app);drop(core);root.write().unwrap();zip.borrow_mut().close().unwrap();let bytes=bytes.0.borrow();let mut input=zip::ZipArchive::new(Cursor::new(&*bytes)).unwrap();let mut entries=vec![];for i in 0..input.len(){let mut e=input.by_index(i).unwrap();let mut content=String::new();e.read_to_string(&mut content).unwrap();entries.push(json!({"name":e.name(),"method":e.compression().to_u16(),"size":e.size(),"crc":e.crc32(),"content":content}));}out["entries"]=json!(entries);out
}
fn exception(e:Box<dyn std::any::Any+Send>)->String{let text=e.downcast_ref::<String>().cloned().or_else(||e.downcast_ref::<&str>().map(|s|s.to_string())).unwrap_or_default();for name in ["IllegalArgumentException","IllegalStateException","NullPointerException"]{if text.contains(name){return name.into();}}panic!("unexpected native panic: {text}")}
#[test]
fn original_android_opcw_part_relationships_and_property_zip_entries(){
    let p=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("rewrite-review/milestones/m4-edit-save/evidence/recognise-r0b27");let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let expected=&java["opcw"];let mut packages=vec![];for mask in 0..8{let actual=package_case(mask);assert_eq!(actual,expected["packages"][mask as usize],"package mask {mask}");packages.push(actual);}
    let mut paths=vec![];for row in expected["paths"].as_array().unwrap(){let a=row["a"].as_str().unwrap();let b=row["b"].as_str().unwrap();let mut actual=json!({"a":a,"b":b});for kind in 0..4{let r=std::panic::catch_unwind(||match kind{0=>OpcUtil::getRelsesName(a),1=>OpcUtil::getRelsTarget(Some(a),Some(b)),2=>OpcUtil::getPartName(Some(a),Some(b)),_=>OpcUtil::getPartNamex(a,b)});actual[format!("k{kind}")]=json!(r.unwrap_or_else(exception));}assert_eq!(actual,*row);paths.push(actual);}
    let mut dates=vec![];for row in expected["dates"].as_array().unwrap(){let millis=row["millis"].as_i64().unwrap();let a=json!({"millis":millis,"out":OpcUtil::getDateString(millis)});assert_eq!(a,*row);dates.push(a);}
    let actual=json!({"packages":packages,"paths":paths,"dates":dates});assert_eq!(actual,*expected);std::fs::write(p.join("rust-opcw.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();
}
